  /**
   * @method
   * @name luno#createOrder
   * @description create a trade order
   * @see
   * https://www.luno.com/en/developers/api#tag/Orders/operation/PostMarketOrder
   * @see
   * https://www.luno.com/en/developers/api#tag/Orders/operation/PostLimitOrder
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
              ccxt::any amount, ccxt::any price = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("pair"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(side, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " createOrder() requires a side argument"))));
                 }
                 if (isTrue(isEqual(type, std::string("market")))) {
                   ::setValue(request, std::string("type"), toUpperCase(side));
                   // todo add createMarketBuyOrderRequires price logic as it is
                   // implemented in the other exchanges
                   if (isTrue(isEqual(side, std::string("buy")))) {
                     ::setValue(request, std::string("counter_volume"),
                                this->amountToPrecision(
                                    ::getValue(market, std::string("symbol")),
                                    amount));
                   } else {
                     ::setValue(request, std::string("base_volume"),
                                this->amountToPrecision(
                                    ::getValue(market, std::string("symbol")),
                                    amount));
                   }
                   response = awaitValue(this->privatePostMarketorder(
                       this->extend(request, params)));
                 } else {
                   ::setValue(
                       request, std::string("volume"),
                       this->amountToPrecision(
                           ::getValue(market, std::string("symbol")), amount));
                   ::setValue(
                       request, std::string("price"),
                       this->priceToPrecision(
                           ::getValue(market, std::string("symbol")), price));
                   ::setValue(request, std::string("type"),
                              (isTrue((isEqual(side, std::string("buy"))))
                                   ? ccxt::any(std::string("BID"))
                                   : ccxt::any(std::string("ASK"))));
                   response = awaitValue(this->privatePostPostorder(
                       this->extend(request, params)));
                 }
                 if (isTrue(isEqual(response, ccxt::any{}))) {
                   throw NullResponse(toString(add(
                       this->id,
                       std::string(" createOrder() returned empty response"))));
                 }
                 return this->safeOrder(
                     ccxt::dict{
                         {std::string("info"), response},
                         {std::string("id"),
                          ::getValue(response, std::string("order_id"))},
                     },
                     market);
               })
        .share();
  }

